  INSERT INTO class_subjects (class_id, subject_id) VALUES (c10_id, sci_id) ON CONFLICT DO NOTHING;
  INSERT INTO questions (school_id, subject_id, question_type, question_text, options, answer, marks, difficulty, chapters, tags, is_active) VALUES
  (sid, sci_id, 'mcq', 'An example for chemical change among the following is', '[{"key": "A", "value": "Dissolving salt in water", "correct": false}, {"key": "B", "value": "Tearing of paper", "correct": false}, {"key": "C", "value": "Rusting of iron", "correct": true}, {"key": "D", "value": "Boiling of water", "correct": false}]', 'C', 1, 'easy', '["Chemical Reactions and Equations"]', '["chemical_change"]', true),
  (sid, sci_id, 'mcq', 'This is not a property of a chemical reaction among the following is', '[{"key": "A", "value": "Change in colour", "correct": false}, {"key": "B", "value": "Release of heat", "correct": false}, {"key": "C", "value": "Change in shape", "correct": true}, {"key": "D", "value": "Release of gas", "correct": false}]', 'C', 1, 'easy', '["Chemical Reactions and Equations"]', '["properties"]', true),
  (sid, sci_id, 'mcq', 'The chemical reaction \[\ce{Fe2O3 + 2Al -> Al2O3 + 2Fe}\] is an example for', '[{"key": "A", "value": "Combination reaction", "correct": false}, {"key": "B", "value": "Decomposition reaction", "correct": false}, {"key": "C", "value": "Displacement reaction", "correct": true}, {"key": "D", "value": "Double displacement reaction", "correct": false}]', 'C', 1, 'medium', '["Chemical Reactions and Equations"]', '["displacement_reaction"]', true),
  (sid, sci_id, 'mcq', 'The group of reactants among the following which react with each other to exchange ions and form a precipitate is', '[{"key": "A", "value": "\\(\\ce{BaCl2}\\) and \\(\\ce{Na2SO4}\\)", "correct": true}, {"key": "B", "value": "\\(\\ce{Al2O3}\\) and \\(\\ce{HCl}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{NaOH}\\) and \\(\\ce{H2SO4}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{Na2O}\\) and \\(\\ce{CO2}\\)", "correct": false}]', 'A', 1, 'medium', '["Chemical Reactions and Equations"]', '["precipitation_reaction"]', true),
  (sid, sci_id, 'mcq', 'The evolution of Oxygen and Hydrogen gases in the electrolysis of water. This reaction is', '[{"key": "A", "value": "Displacement reaction", "correct": false}, {"key": "B", "value": "Exothermic reaction", "correct": false}, {"key": "C", "value": "Endothermic reaction", "correct": true}, {"key": "D", "value": "Redox reaction", "correct": false}]', 'C', 1, 'medium', '["Chemical Reactions and Equations"]', '["electrolysis"]', true),
  (sid, sci_id, 'mcq', 'The chemical reaction that takes place when reactants exchange their ions mutually is', '[{"key": "A", "value": "Double displacement reaction", "correct": true}, {"key": "B", "value": "Displacement reaction", "correct": false}, {"key": "C", "value": "Decomposition reaction", "correct": false}, {"key": "D", "value": "Combination reaction", "correct": false}]', 'A', 1, 'medium', '["Chemical Reactions and Equations"]', '["double_displacement"]', true),
  (sid, sci_id, 'mcq', 'In the reaction \(\ce{CuO + H2 -> Cu + H2O}\), the reactants that undergo oxidation and reduction respectively are', '[{"key": "A", "value": "\\(\\ce{CuO}\\) and \\(\\ce{H2}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{H2}\\) and \\(\\ce{CuO}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{Cu}\\) and \\(\\ce{H2O}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{H2O}\\) and \\(\\ce{Cu}\\)", "correct": false}]', 'B', 1, 'hard', '["Chemical Reactions and Equations"]', '["redox"]', true),
  (sid, sci_id, 'mcq', 'Silver chloride turns into grey colour in the presence of sunlight because', '[{"key": "A", "value": "Silver chloride decomposes to form silver and chlorine", "correct": true}, {"key": "B", "value": "Silver chloride decomposes to form only chlorine", "correct": false}, {"key": "C", "value": "Silver chloride decomposes to form only silver", "correct": false}, {"key": "D", "value": "Silver chloride does not decompose", "correct": false}]', 'A', 1, 'medium', '["Chemical Reactions and Equations"]', '["photolytic_decomposition"]', true),
  (sid, sci_id, 'mcq', 'The ratio of hydrogen and oxygen gases released in the electrolysis of water is', '[{"key": "A", "value": "Hydrogen: Oxygen :: \\((1:2)\\)", "correct": false}, {"key": "B", "value": "Oxygen: Hydrogen :: \\((2:3)\\)", "correct": false}, {"key": "C", "value": "Hydrogen: Oxygen :: \\((2:1)\\)", "correct": true}, {"key": "D", "value": "Oxygen: Hydrogen :: \\((3:2)\\)", "correct": false}]', 'C', 1, 'medium', '["Chemical Reactions and Equations"]', '["electrolysis"]', true),
  (sid, sci_id, 'mcq', 'Due to breakdown of vegetable waste compost will be formed. This is an example for', '[{"key": "A", "value": "Reduction reaction", "correct": false}, {"key": "B", "value": "Exothermic reaction", "correct": true}, {"key": "C", "value": "Endothermic reaction", "correct": false}, {"key": "D", "value": "Redox reaction", "correct": false}]', 'B', 1, 'medium', '["Chemical Reactions and Equations"]', '["exothermic"]', true),
  (sid, sci_id, 'mcq', 'The gas released at the cathode in the electrolysis of water is', '[{"key": "A", "value": "Oxygen", "correct": false}, {"key": "B", "value": "Hydrogen", "correct": true}, {"key": "C", "value": "Chlorine", "correct": false}, {"key": "D", "value": "Nitrogen", "correct": false}]', 'B', 1, 'easy', '["Chemical Reactions and Equations"]', '["electrolysis"]', true),
  (sid, sci_id, 'mcq', 'Identify the chemical equation in which the chemical reaction takes place in the following:', '[{"key": "A", "value": "\\(\\ce{FeSO4 + Pb -> PbSO4 + Fe}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{ZnSO4 + Fe -> FeSO4 + Zn}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{2AgNO3 + Cu -> Cu(NO3)2 + 2Ag}\\)", "correct": true}, {"key": "D", "value": "\\(\\ce{PbCl2 + Cu -> CuCl2 + Pb}\\)", "correct": false}]', 'C', 1, 'hard', '["Chemical Reactions and Equations"]', '["reactivity"]', true),
  (sid, sci_id, 'mcq', 'When dilute hydrochloric acid is added to iron filings:', '[{"key": "A", "value": "Hydrogen gas and iron chloride are produced", "correct": true}, {"key": "B", "value": "Chlorine gas and ferric hydroxide are produced", "correct": false}, {"key": "C", "value": "No reaction takes place", "correct": false}, {"key": "D", "value": "Iron salt and water are produced", "correct": false}]', 'A', 1, 'easy', '["Chemical Reactions and Equations"]', '["acid_metal"]', true),
  (sid, sci_id, 'mcq', 'The metal that displaces copper from copper sulphate is', '[{"key": "A", "value": "Gold", "correct": false}, {"key": "B", "value": "Silver", "correct": false}, {"key": "C", "value": "Copper", "correct": false}, {"key": "D", "value": "Iron", "correct": true}]', 'D', 1, 'easy', '["Chemical Reactions and Equations"]', '["displacement"]', true),
  (sid, sci_id, 'mcq', 'Ferrous sulphate crystals lose their green colour when heated because this compound', '[{"key": "A", "value": "Breaks down into simpler compounds", "correct": false}, {"key": "B", "value": "Loses water molecules", "correct": true}, {"key": "C", "value": "Releases sulphur dioxide gas", "correct": false}, {"key": "D", "value": "Produces brown smoke", "correct": false}]', 'B', 1, 'medium', '["Chemical Reactions and Equations"]', '["heating_crystals"]', true),
  (sid, sci_id, 'mcq', 'Chips manufacturers flush bags of chips with nitrogen gas because', '[{"key": "A", "value": "To prevent corrosion", "correct": false}, {"key": "B", "value": "To prevent oxidation", "correct": true}, {"key": "C", "value": "To cause corrosion", "correct": false}, {"key": "D", "value": "To prevent reduction", "correct": false}]', 'B', 1, 'easy', '["Chemical Reactions and Equations"]', '["antioxidant"]', true),
  (sid, sci_id, 'mcq', 'The chemical reaction in which iron undergoes corrosion is', '[{"key": "A", "value": "combination and redox reaction", "correct": true}, {"key": "B", "value": "displacement and redox reaction", "correct": false}, {"key": "C", "value": "redox and oxidation reaction", "correct": false}, {"key": "D", "value": "displacement and oxidation reaction", "correct": false}]', 'A', 1, 'medium', '["Chemical Reactions and Equations"]', '["corrosion"]', true),
  (sid, sci_id, 'mcq', 'In the reaction \(\ce{MnO2 + 4HCl -> MnCl2 + 2H2O + Cl2}\), the oxidized and reduced compounds respectively are', '[{"key": "A", "value": "\\(\\ce{MnO2}\\) and \\(\\ce{HCl}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{HCl}\\) and \\(\\ce{MnO2}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{MnO2}\\) and \\(\\ce{H2O}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{MnO2}\\) and \\(\\ce{Cl2}\\)", "correct": false}]', 'B', 1, 'medium', '["Chemical Reactions and Equations"]', '["redox"]', true),
  (sid, sci_id, 'mcq', 'When the chemical equation \(\ce{a Pb(NO3)2 ->[heat] b PbO + c NO2 + d O2}\) is balanced, the values of a, b, c and d respectively are', '[{"key": "A", "value": "2, 2, 3, 2", "correct": false}, {"key": "B", "value": "2, 2, 4, 1", "correct": true}, {"key": "C", "value": "3, 2, 3, 1", "correct": false}, {"key": "D", "value": "2, 2, 3, 3", "correct": false}]', 'B', 1, 'hard', '["Chemical Reactions and Equations"]', '["balancing"]', true),
  (sid, sci_id, 'mcq', 'A situation where a chemical change occurs is', '[{"key": "A", "value": "Sugar is dissolved in water", "correct": false}, {"key": "B", "value": "Paper is being torn", "correct": false}, {"key": "C", "value": "Grape fermented", "correct": true}, {"key": "D", "value": "Boiling of water", "correct": false}]', 'C', 1, 'easy', '["Chemical Reactions and Equations"]', '["chemical_change"]', true),
  (sid, sci_id, 'mcq', 'An observation that helps us to decide the rusting of iron is', '[{"key": "A", "value": "Change in colour", "correct": true}, {"key": "B", "value": "Change in temperature", "correct": false}, {"key": "C", "value": "Change in state", "correct": false}, {"key": "D", "value": "Evolution of gas", "correct": false}]', 'A', 1, 'easy', '["Chemical Reactions and Equations"]', '["rusting"]', true),
  (sid, sci_id, 'mcq', 'On heating calcium carbonate, it produces calcium oxide and carbon dioxide. This reaction is a', '[{"key": "A", "value": "Combination reaction", "correct": false}, {"key": "B", "value": "Decomposition reaction", "correct": true}, {"key": "C", "value": "Displacement reaction", "correct": false}, {"key": "D", "value": "Double displacement reaction", "correct": false}]', 'B', 1, 'easy', '["Chemical Reactions and Equations"]', '["decomposition"]', true),
  (sid, sci_id, 'mcq', 'Combustion of coal is an example of', '[{"key": "A", "value": "Combination reaction", "correct": true}, {"key": "B", "value": "Decomposition reaction", "correct": false}, {"key": "C", "value": "Displacement reaction", "correct": false}, {"key": "D", "value": "Double displacement reaction", "correct": false}]', 'A', 1, 'easy', '["Chemical Reactions and Equations"]', '["combination"]', true),
  (sid, sci_id, 'mcq', 'The chemical equation that represents neutralization reaction among the following is', '[{"key": "A", "value": "\\(\\ce{BaCl2 + H2SO4 -> BaSO4 + 2HCl}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{MnO2 + 4HCl -> MnCl2 + 2H2O + Cl2}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{2NaOH + H2SO4 -> Na2SO4 + 2H2O}\\)", "correct": true}, {"key": "D", "value": "\\(\\ce{AgNO3 + HCl -> AgCl + HNO3}\\)", "correct": false}]', 'C', 1, 'medium', '["Acids, Bases and Salts"]', '["neutralization"]', true),
  (sid, sci_id, 'mcq', 'As the pH value of a neutral solution increases, the', '[{"key": "A", "value": "basic property decreases and number of \\(\\ce{OH-}\\) ions increases", "correct": false}, {"key": "B", "value": "acidic property increases and number of \\(\\ce{H+}\\) ions decreases", "correct": false}, {"key": "C", "value": "basic property increases and number of \\(\\ce{OH-}\\) ions increases", "correct": true}, {"key": "D", "value": "acidic property decreases and number of \\(\\ce{H+}\\) ions increases", "correct": false}]', 'C', 1, 'medium', '["Acids, Bases and Salts"]', '["pH_scale"]', true),
  (sid, sci_id, 'mcq', 'A compound that reacts with both acids as well as bases to produce salts and water is', '[{"key": "A", "value": "Aluminium Oxide", "correct": true}, {"key": "B", "value": "Copper Oxide", "correct": false}, {"key": "C", "value": "Iron Oxide", "correct": false}, {"key": "D", "value": "Sodium Oxide", "correct": false}]', 'A', 1, 'hard', '["Acids, Bases and Salts"]', '["amphoteric_oxides"]', true),
  (sid, sci_id, 'mcq', 'The gas liberated when sodium carbonate reacts with dilute hydrochloric acid is', '[{"key": "A", "value": "Carbon Dioxide", "correct": true}, {"key": "B", "value": "Nitrogen Dioxide", "correct": false}, {"key": "C", "value": "Hydrogen", "correct": false}, {"key": "D", "value": "Chlorine", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["carbonate_reaction"]', true),
  (sid, sci_id, 'mcq', 'The substance that converts blue litmus paper into red colour is', '[{"key": "A", "value": "Lime water", "correct": false}, {"key": "B", "value": "Pure water", "correct": false}, {"key": "C", "value": "Sodium hydroxide solution", "correct": false}, {"key": "D", "value": "Gastric juice", "correct": true}]', 'D', 1, 'easy', '["Acids, Bases and Salts"]', '["litmus"]', true),
  (sid, sci_id, 'mcq', 'An acid present in the stinging hair of nettle plant leaves is', '[{"key": "A", "value": "Methanoic acid", "correct": true}, {"key": "B", "value": "Oxalic acid", "correct": false}, {"key": "C", "value": "Citric acid", "correct": false}, {"key": "D", "value": "Lactic acid", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["stinging_hair"]', true),
  (sid, sci_id, 'mcq', 'The compound used to remove the permanent hardness of water is', '[{"key": "A", "value": "Sodium carbonate", "correct": true}, {"key": "B", "value": "Sodium hydroxide", "correct": false}, {"key": "C", "value": "Sodium hydrogen carbonate", "correct": false}, {"key": "D", "value": "Sodium chloride", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["water_hardness"]', true),
  (sid, sci_id, 'mcq', 'The pH value range of an acid is', '[{"key": "A", "value": "0-7", "correct": true}, {"key": "B", "value": "2-12", "correct": false}, {"key": "C", "value": "7-14", "correct": false}, {"key": "D", "value": "12-14", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["pH_range"]', true),
  (sid, sci_id, 'mcq', 'As the number of hydrogen ions increases in a solution, it becomes', '[{"key": "A", "value": "Neutral", "correct": false}, {"key": "B", "value": "Acidic", "correct": true}, {"key": "C", "value": "Basic", "correct": false}, {"key": "D", "value": "Amphoteric", "correct": false}]', 'B', 1, 'easy', '["Acids, Bases and Salts"]', '["hydrogen_ions"]', true),
  (sid, sci_id, 'mcq', 'When the dilute sulphuric acid is mixed with lead the gas released is', '[{"key": "A", "value": "oxygen", "correct": false}, {"key": "B", "value": "nitrogen", "correct": false}, {"key": "C", "value": "Hydrogen", "correct": true}, {"key": "D", "value": "carbon", "correct": false}]', 'C', 1, 'medium', '["Acids, Bases and Salts"]', '["dilute_acid"]', true),
  (sid, sci_id, 'mcq', 'When an acid is mixed with a metal the products obtained are', '[{"key": "A", "value": "Metal oxide & water", "correct": false}, {"key": "B", "value": "Salt & water", "correct": false}, {"key": "C", "value": "Metal oxide & hydrogen gas", "correct": false}, {"key": "D", "value": "Salt & hydrogen gas", "correct": true}]', 'D', 1, 'easy', '["Acids, Bases and Salts"]', '["acid_metal"]', true),
  (sid, sci_id, 'mcq', 'The molecular formula of lime water is', '[{"key": "A", "value": "\\(\\ce{CaO}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{Ca(OH)2}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{CaCO3}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{CO2}\\)", "correct": false}]', 'B', 1, 'easy', '["Acids, Bases and Salts"]', '["lime_water"]', true),
  (sid, sci_id, 'mcq', 'When hydrochloric acid is added to a copper oxide solution, its colour turns into blue-green due to the formation of', '[{"key": "A", "value": "Copper oxide", "correct": false}, {"key": "B", "value": "Water", "correct": false}, {"key": "C", "value": "Copper hydroxide", "correct": false}, {"key": "D", "value": "Copper chloride", "correct": true}]', 'D', 1, 'medium', '["Acids, Bases and Salts"]', '["copper_oxide_reaction"]', true),
  (sid, sci_id, 'mcq', 'An acid should be added to water, not water to acid. Because the process is highly', '[{"key": "A", "value": "Exothermic and may explode or splash", "correct": true}, {"key": "B", "value": "Endothermic and may freeze the container", "correct": false}, {"key": "C", "value": "Non-reactive unless heated", "correct": false}, {"key": "D", "value": "None of the above", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["acid_dilution"]', true),
  (sid, sci_id, 'mcq', 'To obtain an acidic salt, which kind of acid and base have to be reacted with each other?', '[{"key": "A", "value": "Weak base and weak acid", "correct": false}, {"key": "B", "value": "Weak acid and strong base", "correct": false}, {"key": "C", "value": "Strong acid and strong base", "correct": false}, {"key": "D", "value": "Strong acid and weak base", "correct": true}]', 'D', 1, 'medium', '["Acids, Bases and Salts"]', '["salt_nature"]', true),
  (sid, sci_id, 'mcq', 'Two solutions M and N are tested with red and blue litmus papers. Which of the following statements is correct?', '[{"key": "A", "value": "If M is a metallic oxide solution, the blue litmus turns red", "correct": false}, {"key": "B", "value": "If N is a metallic oxide solution, the red litmus does not change colour", "correct": false}, {"key": "C", "value": "If M is a non-metallic oxide solution, the blue litmus turns red", "correct": true}, {"key": "D", "value": "If N is a non-metallic oxide solution, the red litmus turns blue", "correct": false}]', 'C', 1, 'hard', '["Acids, Bases and Salts"]', '["litmus_oxides"]', true),
  (sid, sci_id, 'mcq', 'In the reaction \(\ce{X + Y -> Salt + Water}\), which pair represents X and Y to show a typical neutralization?', '[{"key": "A", "value": "\\(\\ce{BaCl2}\\) and \\(\\ce{H2SO4}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{MnO2}\\) and \\(\\ce{HCl}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{NaOH}\\) and \\(\\ce{HCl}\\)", "correct": true}, {"key": "D", "value": "\\(\\ce{AgNO3}\\) and \\(\\ce{HCl}\\)", "correct": false}]', 'C', 1, 'easy', '["Acids, Bases and Salts"]', '["neutralization_pair"]', true),
  (sid, sci_id, 'mcq', 'Which of the following solutions will turn red litmus paper to blue?', '[{"key": "A", "value": "\\(\\ce{CH3COOH}\\) and \\(\\ce{HCOOH}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{NaOH}\\) and \\(\\ce{Ca(OH)2}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{NaOH}\\) and \\(\\ce{CH3COOH}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{Ca(OH)2}\\) and \\(\\ce{HCOOH}\\)", "correct": false}]', 'B', 1, 'easy', '["Acids, Bases and Salts"]', '["litmus_basic"]', true),
  (sid, sci_id, 'mcq', 'Which compound is used for bleaching cotton and linen in the textile industry?', '[{"key": "A", "value": "\\(\\ce{CaOCl2}\\)", "correct": true}, {"key": "B", "value": "\\(\\ce{NaOH}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{Na2CO3}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{NaCl}\\)", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["bleaching_powder"]', true),
  (sid, sci_id, 'mcq', 'Tooth decay starts when the pH of our mouth is', '[{"key": "A", "value": "Less than 5.5", "correct": true}, {"key": "B", "value": "6 to 7", "correct": false}, {"key": "C", "value": "8 to 9", "correct": false}, {"key": "D", "value": "Above 10", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["tooth_decay"]', true),
  (sid, sci_id, 'mcq', 'The products obtained when metal pieces are added to an acid are', '[{"key": "A", "value": "Metallic oxide and water", "correct": false}, {"key": "B", "value": "Salt and water", "correct": false}, {"key": "C", "value": "Metallic oxide and hydrogen gas", "correct": false}, {"key": "D", "value": "Salt and hydrogen gas", "correct": true}]', 'D', 1, 'easy', '["Acids, Bases and Salts"]', '["metal_acid_products"]', true),
  (sid, sci_id, 'mcq', 'In the chemical reaction: Metallic oxide + hydrochloric acid -> X + water (blue-green colour solution), the product X is', '[{"key": "A", "value": "Copper (II) Oxide", "correct": false}, {"key": "B", "value": "Copper (II) Carbonate", "correct": false}, {"key": "C", "value": "Copper (II) Sulphate", "correct": false}, {"key": "D", "value": "Copper (II) Chloride", "correct": true}]', 'D', 1, 'medium', '["Acids, Bases and Salts"]', '["copper_chloride"]', true),
  (sid, sci_id, 'mcq', 'In the reaction \(\ce{X + Y -> Salt + Water}\), to obtain an acidic salt the reactants X and Y respectively must be', '[{"key": "A", "value": "Weak base and Weak acid", "correct": false}, {"key": "B", "value": "Weak base and Strong acid", "correct": false}, {"key": "C", "value": "Strong base and Strong acid", "correct": true}, {"key": "D", "value": "Strong base and Weak acid", "correct": false}]', 'C', 1, 'medium', '["Acids, Bases and Salts"]', '["acidic_salt_reactants"]', true),
  (sid, sci_id, 'mcq', 'Match the natural sources (Ant sting, Sour milk, Tomato, Orange) with their respective acids:', '[{"key": "A", "value": "Methanoic acid, Lactic acid, Oxalic acid and Citric acid", "correct": true}, {"key": "B", "value": "Acetic acid, Lactic acid, Oxalic acid and Citric acid", "correct": false}, {"key": "C", "value": "Methanoic acid, Citric acid, Oxalic acid and Lactic acid", "correct": false}, {"key": "D", "value": "Tartaric acid, Citric acid, Oxalic acid and Lactic acid", "correct": false}]', 'A', 1, 'easy', '["Acids, Bases and Salts"]', '["natural_acids_match"]', true),
  (sid, sci_id, 'mcq', 'The ions responsible for the basic property of a solution are', '[{"key": "A", "value": "\\(\\ce{H+}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{OH-}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{H+}\\) and \\(\\ce{OH-}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{H+}\\) and \\(\\ce{Cl-}\\)", "correct": false}]', 'B', 1, 'easy', '["Acids, Bases and Salts"]', '["basic_ions"]', true),
  (sid, sci_id, 'mcq', 'The group of reactants that will give a displacement reaction is', '[{"key": "A", "value": "\\(\\ce{NaCl}\\) solution and copper metal", "correct": false}, {"key": "B", "value": "\\(\\ce{MgCl2}\\) solution and aluminium metal", "correct": false}, {"key": "C", "value": "\\(\\ce{FeSO4}\\) solution and silver metal", "correct": false}, {"key": "D", "value": "\\(\\ce{AgNO3}\\) solution and copper metal", "correct": true}]', 'D', 1, 'easy', '["Metals and Non-Metals"]', '["displacement"]', true),
  (sid, sci_id, 'mcq', 'Food cans are coated with tin and not with zinc because', '[{"key": "A", "value": "Zinc is more expensive than tin", "correct": false}, {"key": "B", "value": "The melting point of zinc is higher than that of tin", "correct": false}, {"key": "C", "value": "Zinc is more reactive than tin", "correct": true}, {"key": "D", "value": "Zinc is less reactive than tin", "correct": false}]', 'C', 1, 'medium', '["Metals and Non-Metals"]', '["reactivity"]', true),
  (sid, sci_id, 'mcq', 'The gas released when metals react with an acid is', '[{"key": "A", "value": "\\(\\ce{H2}\\)", "correct": true}, {"key": "B", "value": "\\(\\ce{CO2}\\)", "correct": false}, {"key": "C", "value": "\\(\\ce{SO2}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{NO2}\\)", "correct": false}]', 'A', 1, 'easy', '["Metals and Non-Metals"]', '["metal_acid"]', true),
  (sid, sci_id, 'mcq', 'Copper reacts with moist carbon dioxide in the air to produce a green coat of', '[{"key": "A", "value": "Copper carbonate", "correct": true}, {"key": "B", "value": "Copper chloride", "correct": false}, {"key": "C", "value": "Copper nitrate", "correct": false}, {"key": "D", "value": "Copper oxide", "correct": false}]', 'A', 1, 'medium', '["Metals and Non-Metals"]', '["copper_carbonate"]', true),
  (sid, sci_id, 'mcq', 'Based on the displacement reactions: \(\ce{CuSO4 + Fe -> FeSO4 + Cu}\) and \(\ce{2AgNO3 + Cu -> Cu(NO3)2 + 2Ag}\), identify the correct statement:', '[{"key": "A", "value": "Copper is more reactive than iron and silver", "correct": false}, {"key": "B", "value": "Iron is less reactive than copper and silver", "correct": false}, {"key": "C", "value": "Copper is more reactive than silver but less reactive than iron", "correct": true}, {"key": "D", "value": "Silver is more reactive than copper and iron", "correct": false}]', 'C', 1, 'medium', '["Metals and Non-Metals"]', '["reactivity"]', true),
  (sid, sci_id, 'mcq', 'The electron configuration of element X is 2, 8, 8, 1 and element Y is 2, 8, 7. The type of bond formed between them is', '[{"key": "A", "value": "Covalent bond", "correct": false}, {"key": "B", "value": "Metallic bond", "correct": false}, {"key": "C", "value": "Hydrogen bond", "correct": false}, {"key": "D", "value": "Ionic bond", "correct": true}]', 'D', 1, 'hard', '["Metals and Non-Metals"]', '["ionic_bond"]', true),
  (sid, sci_id, 'mcq', 'The correct increasing order of reactivity of the metals Al, Na, K, Ca, Mg is', '[{"key": "A", "value": "\\((Al < Mg < Ca < Na < K)\\)", "correct": true}, {"key": "B", "value": "\\((K < Mg < Ca < Na < Al)\\)", "correct": false}, {"key": "C", "value": "\\((K < Na < Ca < Mg < Al)\\)", "correct": false}, {"key": "D", "value": "\\((Al < Na < Mg < Ca < K)\\)", "correct": false}]', 'A', 1, 'hard', '["Metals and Non-Metals"]', '["reactivity_order"]', true),
  (sid, sci_id, 'mcq', 'A process used to convert metal sulphide ores into their oxides by heating strongly in excess air is', '[{"key": "A", "value": "Calcination", "correct": false}, {"key": "B", "value": "Roasting", "correct": true}, {"key": "C", "value": "Reduction", "correct": false}, {"key": "D", "value": "Electrolysis", "correct": false}]', 'B', 1, 'easy', '["Metals and Non-Metals"]', '["roasting"]', true),
  (sid, sci_id, 'mcq', 'A metal which displaces copper from copper sulphate solution is', '[{"key": "A", "value": "Mercury", "correct": false}, {"key": "B", "value": "Gold", "correct": false}, {"key": "C", "value": "Iron", "correct": true}, {"key": "D", "value": "Silver", "correct": false}]', 'C', 1, 'easy', '["Metals and Non-Metals"]', '["displacement_metal"]', true),
  (sid, sci_id, 'mcq', 'Based on the displacement reactions: \(\ce{Fe + CuSO4 -> FeSO4 + Cu}\) and \(\ce{Zn + FeSO4 -> ZnSO4 + Fe}\), the order of decreasing reactivity of the metals is', '[{"key": "A", "value": "\\((Zn > Fe > Cu)\\)", "correct": true}, {"key": "B", "value": "\\((Fe > Cu > Zn)\\)", "correct": false}, {"key": "C", "value": "\\((Zn > Cu > Fe)\\)", "correct": false}, {"key": "D", "value": "\\((Cu > Fe > Zn)\\)", "correct": false}]', 'A', 1, 'medium', '["Metals and Non-Metals"]', '["reactivity_series"]', true),
  (sid, sci_id, 'mcq', 'The number of valence electrons in a carbon atom is', '[{"key": "A", "value": "1", "correct": false}, {"key": "B", "value": "2", "correct": false}, {"key": "C", "value": "3", "correct": false}, {"key": "D", "value": "4", "correct": true}]', 'D', 1, 'easy', '["Carbon and Its Compounds"]', '["valence"]', true),
  (sid, sci_id, 'mcq', 'A molecule formed due to a double bond between its atoms is', '[{"key": "A", "value": "\\(\\ce{Cl2}\\)", "correct": false}, {"key": "B", "value": "\\(\\ce{O2}\\)", "correct": true}, {"key": "C", "value": "\\(\\ce{N2}\\)", "correct": false}, {"key": "D", "value": "\\(\\ce{NH3}\\)", "correct": false}]', 'B', 1, 'medium', '["Carbon and Its Compounds"]', '["double_bond"]', true),
  (sid, sci_id, 'mcq', 'The major component of compressed natural gas is', '[{"key": "A", "value": "propane", "correct": false}, {"key": "B", "value": "butane", "correct": false}, {"key": "C", "value": "methane", "correct": true}, {"key": "D", "value": "ethane", "correct": false}]', 'C', 1, 'easy', '["Carbon and Its Compounds"]', '["cng"]', true),
  (sid, sci_id, 'mcq', 'Carbon bonds with other carbon atoms to form large molecules. This unique property of carbon is', '[{"key": "A", "value": "saponification", "correct": false}, {"key": "B", "value": "catenation", "correct": true}, {"key": "C", "value": "hydrogenation", "correct": false}, {"key": "D", "value": "esterification", "correct": false}]', 'B', 1, 'easy', '["Carbon and Its Compounds"]', '["catenation"]', true),
  (sid, sci_id, 'mcq', 'An unsaturated compound that has a triple bond between carbon atoms is', '[{"key": "A", "value": "methane", "correct": false}, {"key": "B", "value": "ethane", "correct": false}, {"key": "C", "value": "ethene", "correct": false}, {"key": "D", "value": "ethyne", "correct": true}]', 'D', 1, 'easy', '["Carbon and Its Compounds"]', '["alkyne"]', true),
  (sid, sci_id, 'mcq', 'Functional group present in butanol is', '[{"key": "A", "value": "-Cl or -Br", "correct": false}, {"key": "B", "value": "-OH", "correct": true}, {"key": "C", "value": "-CHO", "correct": false}, {"key": "D", "value": "-COOH", "correct": false}]', 'B', 1, 'easy', '["Carbon and Its Compounds"]', '["functional_group"]', true),
  (sid, sci_id, 'mcq', 'The number of single bonds and double bonds present in a structure of benzene molecule respectively are', '[{"key": "A", "value": "6 and 6", "correct": false}, {"key": "B", "value": "9 and 3", "correct": true}, {"key": "C", "value": "7 and 5", "correct": false}, {"key": "D", "value": "3 and 9", "correct": false}]', 'B', 1, 'hard', '["Carbon and Its Compounds"]', '["benzene"]', true),
  (sid, sci_id, 'mcq', 'The number of single bonds present in the structure of a cyclohexane is', '[{"key": "A", "value": "12", "correct": false}, {"key": "B", "value": "18", "correct": true}, {"key": "C", "value": "24", "correct": false}, {"key": "D", "value": "6", "correct": false}]', 'B', 1, 'hard', '["Carbon and Its Compounds"]', '["cyclohexane"]', true),
  (sid, sci_id, 'mcq', 'The correct statement regarding digestion that takes place in the small intestine is', '[{"key": "A", "value": "Acidic food becomes alkaline due to bile.", "correct": true}, {"key": "B", "value": "Food becomes acidic due to hydrochloric acid.", "correct": false}, {"key": "C", "value": "Starch is digested by the action of amylase.", "correct": false}, {"key": "D", "value": "Protein is digested by the action of pepsin.", "correct": false}]', 'A', 1, 'medium', '["Life Processes"]', '["digestion"]', true),
  (sid, sci_id, 'mcq', 'The place where carbohydrates, proteins and fats are completely digested is', '[{"key": "A", "value": "Stomach", "correct": false}, {"key": "B", "value": "Large intestine", "correct": false}, {"key": "C", "value": "Small intestine", "correct": true}, {"key": "D", "value": "Liver", "correct": false}]', 'C', 1, 'easy', '["Life Processes"]', '["complete_digestion"]', true),
  (sid, sci_id, 'mcq', 'Blood vessels that carry blood from all parts of the human body to the heart are', '[{"key": "A", "value": "Arteries", "correct": false}, {"key": "B", "value": "Capillaries", "correct": false}, {"key": "C", "value": "Pulmonary arteries", "correct": false}, {"key": "D", "value": "Veins", "correct": true}]', 'D', 1, 'easy', '["Life Processes"]', '["blood_vessels"]', true),
  (sid, sci_id, 'mcq', 'Transport of soluble photosynthesis products in plants is called', '[{"key": "A", "value": "Evaporation", "correct": false}, {"key": "B", "value": "Osmosis", "correct": false}, {"key": "C", "value": "Diffusion", "correct": false}, {"key": "D", "value": "Translocation", "correct": true}]', 'D', 1, 'easy', '["Life Processes"]', '["translocation"]', true),
  (sid, sci_id, 'mcq', 'An important function of xylem in plants is', '[{"key": "A", "value": "Water transport", "correct": true}, {"key": "B", "value": "Food transport", "correct": false}, {"key": "C", "value": "Amino acid transport", "correct": false}, {"key": "D", "value": "Oxygen transport", "correct": false}]', 'A', 1, 'easy', '["Life Processes"]', '["xylem"]', true),
  (sid, sci_id, 'mcq', 'The place where carbon dioxide and water are released due to the breakdown of pyruvate is', '[{"key": "A", "value": "cytoplasm", "correct": false}, {"key": "B", "value": "mitochondria", "correct": true}, {"key": "C", "value": "chloroplast", "correct": false}, {"key": "D", "value": "nucleus", "correct": false}]', 'B', 1, 'medium', '["Life Processes"]', '["mitochondria"]', true),
  (sid, sci_id, 'mcq', 'The important function of the stomata among the following is', '[{"key": "A", "value": "Exchange of gases", "correct": true}, {"key": "B", "value": "Transport of water and food", "correct": false}, {"key": "C", "value": "Food preparation", "correct": false}, {"key": "D", "value": "Creating osmotic pressure", "correct": false}]', 'A', 1, 'easy', '["Life Processes"]', '["stomata"]', true),
  (sid, sci_id, 'mcq', 'The blood vessel that carries oxygenated blood from the heart is the', '[{"key": "A", "value": "Pulmonary vein", "correct": false}, {"key": "B", "value": "Superior vena cava", "correct": false}, {"key": "C", "value": "Aorta", "correct": true}, {"key": "D", "value": "Pulmonary artery", "correct": false}]', 'C', 1, 'easy', '["Life Processes"]', '["aorta"]', true),
  (sid, sci_id, 'mcq', 'The transpiration process in a plant body helps in', '[{"key": "A", "value": "Balancing the amount of oxygen and water", "correct": false}, {"key": "B", "value": "Establishing a water column in the xylem tissue", "correct": true}, {"key": "C", "value": "Helping in the transport of soluble photosynthesis products", "correct": false}, {"key": "D", "value": "Creating osmotic pressure", "correct": false}]', 'B', 1, 'medium', '["Life Processes"]', '["transpiration"]', true),
  (sid, sci_id, 'mcq', 'The need for suction pressure in plants is', '[{"key": "A", "value": "To overcome the difference in ion concentration between the root and the soil", "correct": false}, {"key": "B", "value": "To transport food in two directions", "correct": false}, {"key": "C", "value": "To carry water to higher parts", "correct": true}, {"key": "D", "value": "To remove excess water from the leaves", "correct": false}]', 'C', 1, 'medium', '["Life Processes"]', '["suction_pressure"]', true),
  (sid, sci_id, 'mcq', 'The incorrect statement related to thyroxin hormone among the following is', '[{"key": "A", "value": "it regulates fat metabolism", "correct": false}, {"key": "B", "value": "its deficiency leads to goitre", "correct": false}, {"key": "C", "value": "it is secreted by parathyroid gland", "correct": true}, {"key": "D", "value": "iodine in the food is essential for its production", "correct": false}]', 'C', 1, 'medium', '["Control and Coordination"]', '["thyroxin"]', true),
  (sid, sci_id, 'mcq', 'The gap between two neurons is called', '[{"key": "A", "value": "dendrite", "correct": false}, {"key": "B", "value": "synapse", "correct": true}, {"key": "C", "value": "axon", "correct": false}, {"key": "D", "value": "impulse", "correct": false}]', 'B', 1, 'easy', '["Control and Coordination"]', '["synapse"]', true),
  (sid, sci_id, 'mcq', 'The following is an example of reflex action:', '[{"key": "A", "value": "sliding the chair", "correct": false}, {"key": "B", "value": "Applause at the end of the program", "correct": false}, {"key": "C", "value": "Pulling hand back when touching a sharp object", "correct": true}, {"key": "D", "value": "Tasting food", "correct": false}]', 'C', 1, 'easy', '["Control and Coordination"]', '["reflex_action"]', true),
  (sid, sci_id, 'mcq', 'If the roots of a plant grow towards an area of nitrate concentration, it is an example of', '[{"key": "A", "value": "Phototropism", "correct": false}, {"key": "B", "value": "Hydrotropism", "correct": false}, {"key": "C", "value": "Thigmotropism", "correct": false}, {"key": "D", "value": "Chemotropism", "correct": true}]', 'D', 1, 'easy', '["Control and Coordination"]', '["chemotropism"]', true),
  (sid, sci_id, 'mcq', 'The correct path of transmission of nerve impulses in the neuron is', '[{"key": "A", "value": "Dendrite -> nerve ending -> cell body -> axon", "correct": false}, {"key": "B", "value": "Dendrite -> Axon -> Cell body -> Nerve ending", "correct": false}, {"key": "C", "value": "Dendrite -> Cell body -> Axon -> Nerve ending", "correct": true}, {"key": "D", "value": "Nerve ending -> Cell body -> Axon -> dendrite", "correct": false}]', 'C', 1, 'medium', '["Control and Coordination"]', '["neuron_transmission"]', true),
  (sid, sci_id, 'mcq', 'An example of positive geotropism in plants is', '[{"key": "A", "value": "Growth of the stem", "correct": false}, {"key": "B", "value": "Growth of roots deep into the soil", "correct": true}, {"key": "C", "value": "Growth of shoots of veins", "correct": false}, {"key": "D", "value": "Upward growth of roots", "correct": false}]', 'B', 1, 'easy', '["Control and Coordination"]', '["geotropism"]', true),
  (sid, sci_id, 'mcq', 'A pot with growing seedling is kept in a dark room. A burning candle is placed near it for a few days. The top part of the seedling bends towards the light. This is', '[{"key": "A", "value": "Chemotropism", "correct": false}, {"key": "B", "value": "Phototropism", "correct": true}, {"key": "C", "value": "Geotropism", "correct": false}, {"key": "D", "value": "Hydrotropism", "correct": false}]', 'B', 1, 'hard', '["Control and Coordination"]', '["phototropism"]', true),
  (sid, sci_id, 'mcq', 'Blood sugar level increases : Under secretion of insulin hormone :: Swelling of the neck :', '[{"key": "A", "value": "Under secretion of thyroxine hormone", "correct": true}, {"key": "B", "value": "More secretion of insulin hormone", "correct": false}, {"key": "C", "value": "More secretion of thyroxine hormone", "correct": false}, {"key": "D", "value": "Excess intake of iodine", "correct": false}]', 'A', 1, 'medium', '["Control and Coordination"]', '["swelling_neck"]', true),
  (sid, sci_id, 'mcq', 'The hormone secreted by the pancreas', '[{"key": "A", "value": "regulates metabolic activities", "correct": false}, {"key": "B", "value": "regulates blood sugar level", "correct": true}, {"key": "C", "value": "stimulates the growth in the body organs", "correct": false}, {"key": "D", "value": "increases breathing rate", "correct": false}]', 'B', 1, 'easy', '["Control and Coordination"]', '["pancreas"]', true),
  (sid, sci_id, 'mcq', 'The upward growth of stem in plants is', '[{"key": "A", "value": "Negative geotropism and positive hydrotropism", "correct": false}, {"key": "B", "value": "Positive geotropism and negative hydrotropism", "correct": false}, {"key": "C", "value": "Negative phototropism and positive geotropism", "correct": false}, {"key": "D", "value": "Negative geotropism and positive phototropism", "correct": true}]', 'D', 1, 'medium', '["Control and Coordination"]', '["stem_growth"]', true),
  (sid, sci_id, 'mcq', 'The SI unit of Electric current is', '[{"key": "A", "value": "Ampere (A)", "correct": true}, {"key": "B", "value": "ohm (\\(\\Omega\\))", "correct": false}, {"key": "C", "value": "Volt (V)", "correct": false}, {"key": "D", "value": "Watt (W)", "correct": false}]', 'A', 1, 'easy', '["Electricity"]', '["si_unit"]', true),
  (sid, sci_id, 'mcq', 'The SI unit of Power is', '[{"key": "A", "value": "Ampere (A)", "correct": false}, {"key": "B", "value": "ohm (\\(\\Omega\\))", "correct": false}, {"key": "C", "value": "Volt (V)", "correct": false}, {"key": "D", "value": "Watt (W)", "correct": true}]', 'D', 1, 'easy', '["Electricity"]', '["power_unit"]', true),
  (sid, sci_id, 'mcq', 'The property of the conductor that opposes the flow of charges through it is called', '[{"key": "A", "value": "electric current", "correct": false}, {"key": "B", "value": "electric potential difference", "correct": false}, {"key": "C", "value": "electric resistance", "correct": true}, {"key": "D", "value": "electric power", "correct": false}]', 'C', 1, 'easy', '["Electricity"]', '["resistance"]', true),
  (sid, sci_id, 'mcq', 'The Rate of flow of electric charges is called', '[{"key": "A", "value": "Electric current", "correct": true}, {"key": "B", "value": "Electric potential", "correct": false}, {"key": "C", "value": "Electric resistance", "correct": false}, {"key": "D", "value": "Electric power", "correct": false}]', 'A', 1, 'easy', '["Electricity"]', '["flow_of_charges"]', true),
  (sid, sci_id, 'mcq', 'The work done in bringing a unit charge from one point to another through a conductor is called', '[{"key": "A", "value": "electric current", "correct": false}, {"key": "B", "value": "electric potential difference", "correct": true}, {"key": "C", "value": "electric resistance", "correct": false}, {"key": "D", "value": "electric power", "correct": false}]', 'B', 1, 'medium', '["Electricity"]', '["work_done"]', true),
  (sid, sci_id, 'mcq', 'The Rate of consumption of energy in an electric circuit is called', '[{"key": "A", "value": "electric current", "correct": false}, {"key": "B", "value": "electric potential difference", "correct": false}, {"key": "C", "value": "electric resistance", "correct": false}, {"key": "D", "value": "electric power", "correct": true}]', 'D', 1, 'medium', '["Electricity"]', '["energy_consumption"]', true),
  (sid, sci_id, 'mcq', 'In an electric circuit, the ammeter and voltmeter are generally connected as follows:', '[{"key": "A", "value": "both are connected in parallel", "correct": false}, {"key": "B", "value": "both are connected in series", "correct": false}, {"key": "C", "value": "ammeter in series & voltmeter in parallel", "correct": true}, {"key": "D", "value": "ammeter in parallel & voltmeter in series", "correct": false}]', 'C', 1, 'medium', '["Electricity"]', '["connections"]', true),
  (sid, sci_id, 'mcq', 'The formula that does not represent Ohm''s law is', '[{"key": "A", "value": "\\(V/I=R\\)", "correct": false}, {"key": "B", "value": "\\(V=IR\\)", "correct": false}, {"key": "C", "value": "\\(I=V/R\\)", "correct": false}, {"key": "D", "value": "\\(V=I/R\\)", "correct": true}]', 'D', 1, 'medium', '["Electricity"]', '["ohms_law"]', true),
  (sid, sci_id, 'mcq', 'The net resistance when \((2\ \Omega)\) & \((4\ \Omega)\) resistors are connected in series, and then connected in parallel with another \((4\ \Omega)\) resistor, is', '[{"key": "A", "value": "\\((2\\ \\Omega)\\)", "correct": false}, {"key": "B", "value": "\\((2.4\\ \\Omega)\\)", "correct": true}, {"key": "C", "value": "\\((4\\ \\Omega)\\)", "correct": false}, {"key": "D", "value": "\\((10\\ \\Omega)\\)", "correct": false}]', 'B', 1, 'hard', '["Electricity"]', '["net_resistance"]', true),
  (sid, sci_id, 'mcq', 'A conductor has a resistance of \((27\ \Omega)\). If it is cut into three equal parts and these parts are connected in parallel, its total resistance is', '[{"key": "A", "value": "\\((6\\ \\Omega)\\)", "correct": false}, {"key": "B", "value": "\\((3\\ \\Omega)\\)", "correct": true}, {"key": "C", "value": "\\((9\\ \\Omega)\\)", "correct": false}, {"key": "D", "value": "\\((27\\ \\Omega)\\)", "correct": false}]', 'B', 1, 'hard', '["Electricity"]', '["parallel_cut"]', true),
  (sid, sci_id, 'mcq', 'Inside a solenoid, the magnetic lines of force are parallel straight lines. Therefore, the magnetic field inside the solenoid is', '[{"key": "A", "value": "Very high", "correct": false}, {"key": "B", "value": "Uniform", "correct": true}, {"key": "C", "value": "Zero", "correct": false}, {"key": "D", "value": "Caused by electric current", "correct": false}]', 'B', 1, 'easy', '["Magnetic Effects of Electric Current"]', '["solenoid"]', true),
  (sid, sci_id, 'mcq', 'Which of these is not a characteristic of magnetic lines of force?', '[{"key": "A", "value": "Magnetic lines of force are dense near the poles.", "correct": false}, {"key": "B", "value": "Magnetic lines of force are closed networks.", "correct": false}, {"key": "C", "value": "Magnetic lines of force intersect each other.", "correct": true}, {"key": "D", "value": "Magnetic lines of force are emitted at the north pole and merge at the south pole.", "correct": false}]', 'C', 1, 'medium', '["Magnetic Effects of Electric Current"]', '["field_lines"]', true),
  (sid, sci_id, 'mcq', 'Assume that you are holding a straight conductor carrying current with your right thumb pointing upwards. Then the direction of the magnetic force lines of the magnetic field is', '[{"key": "A", "value": "Downward", "correct": false}, {"key": "B", "value": "Upward", "correct": false}, {"key": "C", "value": "Anticlockwise", "correct": true}, {"key": "D", "value": "Clockwise", "correct": false}]', 'C', 1, 'hard', '["Magnetic Effects of Electric Current"]', '["thumb_rule"]', true),
  (sid, sci_id, 'mcq', 'In Fleming''s left-hand rule, the direction in which the middle finger points represents', '[{"key": "A", "value": "Magnetic field", "correct": false}, {"key": "B", "value": "Electric current", "correct": true}, {"key": "C", "value": "Motion of a conductor", "correct": false}, {"key": "D", "value": "Induced electric current", "correct": false}]', 'B', 1, 'easy', '["Magnetic Effects of Electric Current"]', '["middle_finger"]', true),
  (sid, sci_id, 'mcq', 'If the number of turns in a circular conductor carrying current is increased by 10 times, then the magnetic field produced increases by', '[{"key": "A", "value": "100 times", "correct": false}, {"key": "B", "value": "10 times", "correct": true}, {"key": "C", "value": "20 times", "correct": false}, {"key": "D", "value": "1000 times", "correct": false}]', 'B', 1, 'hard', '["Magnetic Effects of Electric Current"]', '["turns_coil"]', true),
  (sid, sci_id, 'mcq', 'When a magnetic needle is brought near a current-carrying wire, it is deflected. The direction of deflection of the needle depends on', '[{"key": "A", "value": "Length of the conductor", "correct": false}, {"key": "B", "value": "Amount of current in the conductor", "correct": false}, {"key": "C", "value": "Direction of current in the conductor", "correct": true}, {"key": "D", "value": "Strength of the needle", "correct": false}]', 'C', 1, 'medium', '["Magnetic Effects of Electric Current"]', '["needle_deflection"]', true),
  (sid, sci_id, 'mcq', 'If the density of magnetic lines of force is high, the strength of the magnetic field is', '[{"key": "A", "value": "High", "correct": true}, {"key": "B", "value": "Low", "correct": false}, {"key": "C", "value": "Neutral", "correct": false}, {"key": "D", "value": "Zero", "correct": false}]', 'A', 1, 'easy', '["Magnetic Effects of Electric Current"]', '["field_strength"]', true),
  (sid, sci_id, 'mcq', 'In Fleming''s left-hand rule, the finger that represents the magnetic field is', '[{"key": "A", "value": "Index finger", "correct": true}, {"key": "B", "value": "Thumb", "correct": false}, {"key": "C", "value": "Middle finger", "correct": false}, {"key": "D", "value": "Little finger", "correct": false}]', 'A', 1, 'easy', '["Magnetic Effects of Electric Current"]', '["index_finger"]', true),
  (sid, sci_id, 'mcq', 'A safety method used to prevent damage caused by overload in domestic electrical appliances is', '[{"key": "A", "value": "Providing earthing system", "correct": false}, {"key": "B", "value": "Installing electrical transformers", "correct": false}, {"key": "C", "value": "Use of fuses", "correct": true}, {"key": "D", "value": "Installing electricity meter", "correct": false}]', 'C', 1, 'medium', '["Magnetic Effects of Electric Current"]', '["fuse_safety"]', true),
  (sid, sci_id, 'mcq', 'In case of a short circuit, the current in the circuit', '[{"key": "A", "value": "becomes very low.", "correct": false}, {"key": "B", "value": "remains neutral", "correct": false}, {"key": "C", "value": "becomes very high.", "correct": true}, {"key": "D", "value": "changes continuously", "correct": false}]', 'C', 1, 'medium', '["Magnetic Effects of Electric Current"]', '["short_circuit"]', true),
